  let payload;
  if (form) payload = form;
  else if (body !== undefined) { headers['content-type'] = 'application/json'; payload = JSON.stringify(body); }
  const r = await fetch(CF + path, { method, headers, body: payload });
  const j = await r.json().catch(() => null);
  if (!j || !j.success) throw new Error((j && j.errors && j.errors[0] && j.errors[0].message) || ('Cloudflare HTTP ' + r.status));
  return j.result;
