const TG_ACT_PROMPT = { addgb: 'حجم برای افزودن (GB) را بفرست', subgb: 'حجم برای کم کردن (GB) را بفرست', setgb: 'حجم دقیق (GB) را بفرست؛ ۰ = نامحدود', adddays: 'چند روز اضافه شود؟', dev: 'حداکثر تعداد دستگاه را بفرست؛ ۰ = نامحدود', name: 'نام جدید را بفرست (انگلیسی، عدد، - و _)' };
